  "misconception": {
    "pack_id": "M20",
    "wrong": "Пористость рифового известняка сохраняется такой, какой была при образовании.",
    "right": "Первичные поры сокращаются уже при росте рифа: их заполняют корки водорослей, цемент и осадок. При диагенезе сокращение продолжается за счёт выпадения карбонатов.",
    "claims": ["c1", "c2", "c4"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Пористость рифового известняка по образцам керна или шлифов. Как именно её измеряют, в главе не описано.", "claims": [], "hypothesis": true},
      {"text": "Описание того, чем заполнены пустоты: цемент, корки водорослей, детрит, поздние кристаллы.", "claims": [], "hypothesis": true}
    ],
    "outputs": [
      {"text": "Оценка того, какая часть пор могла быть первичной, а какая появилась или заполнилась позже.", "claims": [], "hypothesis": true}
    ],
    "breaks": [
      {"text": "Одна измеренная пористость не показывает, когда и чем пустоты заполнены. Нужна история породы.", "claims": [], "hypothesis": true},
      {"text": "Автор не даёт величин сокращения пористости, поэтому числа для таких оценок из главы не взять.", "claims": [], "hypothesis": false}
    ]
  },
  "it_analogy": {
    "pack_id": null,
    "analogy": "[гипотеза] Диск, на котором свободное место постепенно занимают временные и служебные файлы: свободного места становится меньше, хотя размер диска не менялся.",
    "breaks_where": "Файлы можно удалить и вернуть место. Заполненные поры в породе обратно не освобождаются, а цемент становится частью скелета породы."
  },
  "now_nuance": null,
  "threshold": {
    "is_threshold": false,
    "why": "Важно для понимания пористости, но сама по себе идея не меняет картину курса. Она подготавливает разговор о пустотах, появившихся позже."
  },
  "inefficiency": {
    "inputs": ["[гипотеза] Образцы рифового известняка (керн или шлиф) из нужного интервала.", "[гипотеза] Значения пористости, полученные лабораторным измерением."],
    "manual_steps": ["[гипотеза] Рассмотреть пустоты и определить, чем они заполнены."],
    "judgment_points": ["[гипотеза] Решить, сохранилась ли первичная пора или она заполнена позже."],
    "time": ["[гипотеза] Сравнить много образцов разного состава, чтобы увидеть закономерность."],
    "typical_errors": ["[гипотеза] Принять измеренную пористость за первичную и не учесть заполнение пор."]
  },
